{
  "imports": [
    "from decimal import Decimal",
    "import pytest",
    "from ledger.discounts import percent_discount",
    "from ledger.money import CurrencyMismatchError, Money"
  ],
  "tests": [
    {
      "name": "test_discount_exceeding_cap_is_limited_to_cap",
      "intent": "a discount that would exceed the cap is limited to the cap",
      "code": "# intent: a discount that would exceed the cap is limited to the cap\ndef test_discount_exceeding_cap_is_limited_to_cap():\n    assert percent_discount(Money.of(\"200.00\"), 25, cap=Money.of(\"30.00\")) == Money.of(\"30.00\")\n"
    },
    {
      "name": "test_discount_equal_to_cap_returns_cap",
      "intent": "a discount exactly equal to the cap returns the cap",
      "code": "# intent: a discount exactly equal to the cap returns the cap\ndef test_discount_equal_to_cap_returns_cap():\n    assert percent_discount(Money.of(\"120.00\"), 25, cap=Money.of(\"30.00\")) == Money.of(\"30.00\")\n"
    },
    {
      "name": "test_discount_below_cap_is_unchanged",
      "intent": "a discount below the cap is not modified",
      "code": "# intent: a discount below the cap is not modified\ndef test_discount_below_cap_is_unchanged():\n    assert percent_discount(Money.of(\"200.00\"), 10, cap=Money.of(\"30.00\")) == Money.of(\"20.00\")\n"
    },
    {
      "name": "test_cap_of_zero_limits_discount_to_zero",
      "intent": "a zero cap limits any positive discount to zero",
      "code": "# intent: a zero cap limits any positive discount to zero\ndef test_cap_of_zero_limits_discount_to_zero():\n    assert percent_discount(Money.of(\"100.00\"), 50, cap=Money.zero()) == Money.zero()\n"
    },
    {
      "name": "test_cap_currency_mismatch_raises_error",
      "intent": "a cap in a different currency raises CurrencyMismatchError",
      "code": "# intent: a cap in a different currency raises CurrencyMismatchError\ndef test_cap_currency_mismatch_raises_error():\n    with pytest.raises(CurrencyMismatchError):\n        percent_discount(Money.of(\"100.00\", \"USD\"), 10, cap=Money.of(\"5.00\", \"EUR\"))\n"
    },
    {
      "name": "test_percent_discount_without_cap_returns_full_discount",
      "intent": "without a cap, the full percentage discount is returned",
      "code": "# intent: without a cap, the full percentage discount is returned\ndef test_percent_discount_without_cap_returns_full_discount():\n    assert percent_discount(Money.of(\"80.00\"), 15) == Money.of(\"12.00\")\n"
    }
  ]
}
